    lines = fp.readlines()

print(f"Total lines: {len(lines)}")
assistant_blocks = []
for line in lines:
    line = line.strip()
    if not line: continue
    try:
        obj = json.loads(line)
        if obj.get('type') == 'assistant':
            content = obj.get('message',{}).get('content','')
            if isinstance(content, list):
                texts = [b['text'] for b in content if isinstance(b, dict) and b.get('type') == 'text']
                for t in texts:
                    if len(t) > 100:
                        assistant_blocks.append(t)
            elif isinstance(content, str) and len(content) > 100:
                assistant_blocks.append(content)
    except:
        pass

print(f"Found {len(assistant_blocks)} assistant text blocks")
for i, block in enumerate(assistant_blocks[-3:]):
    print(f"\n=== Block {len(assistant_blocks)-3+i+1} ===")
    print(block[:4000])
    print("...")
